html:
{% set letter_head = frappe.db.get_value("Letter Head","JGB",['image']) %}
<br><img src="{{ letter_head or '' }}" style="max-height:60px" />
<h4 style="text-align:center"><b>{{ doc.report }}</b></h4>
<h4 style="text-align:center"><b>{{ doc.company }}</b></h4>
<h5 style="text-align:center">{{ frappe.utils.format_date(doc.from_date) }} to {{ frappe.utils.format_date(doc.to_date) }}</h5>
{% set data = frd_report(doc) %}
{% set ncols = data.headers|length %}
<table style="width:100%;border-collapse:collapse;font-family:Calibri,Arial,sans-serif;font-size:10px;">
<thead>
<tr>
<th style="text-align:left;border-bottom:2px solid #1F3864;padding:4px">{{ data.headers[0] }}</th>
{% for h in data.headers[1:] %}
<th style="text-align:right;border-bottom:2px solid #1F3864;padding:4px">{{ h }}</th>
{% endfor %}
</tr>
</thead>
<tbody>
{% for r in data.rows %}
{% if r.header %}
<tr><td colspan="{{ ncols }}" style="background:#1F3864;color:#FFFFFF;font-weight:bold;padding:4px">{{ r.label }}</td></tr>
{% else %}
<tr style="{% if r.bold %}font-weight:bold;border-top:1px solid #1F3864;border-bottom:1px solid #1F3864;background:#D9E1F2;{% endif %}">
<td style="padding:2px 4px;padding-left:{{ 4 + r.indent * 14 }}px">{{ r.label }}</td>
{% for v in r.cells %}
<td style="text-align:right;padding:2px 4px">{% if v is not none %}{{ fmt_money(v) }}{% endif %}</td>
{% endfor %}
</tr>
{% endif %}
{% endfor %}
</tbody>
</table>
